mapper.select:
select a.id, a.cell, a.package_id
from b_wuba_colliding_data_rob a join b_local_file b on a.package_id = b.id
where a.is_deleted = 0 and a.api_code = #{apiCode}  and (a.push_time < #{nowDate} or a.push_time is null) 
and b.api_code = #{apiCode} and b.status = 2 and b.complete = 1 and b.push_status = 2 and b.file_name in

    #{fileName}

limit #{pageSize}

select id, cell, package_id from b_wuba_colliding_data_rob
where is_deleted = 0 and package_id = #{loopCycleReavedFileId}
  and api_code = #{apiCode}
   and push_time < #{pushTimeEnd} 
order by push_time
    limit #{pageSize}

select cell
from b_wuba_colliding_data_rob
where is_deleted = 0 and api_code = #{apiCode} and package_id in ${highValueAndReavedFileIds}
and cell in

    #{cell}

select cell
from b_wuba_colliding_data_rob
where is_deleted = 0 and api_code = #{apiCode}
 and (create_time >= #{today} and create_time < #{tomorrow} )
and cell in

